 * Convert a total minutes offset into a standardized timezone offset string.
 *
 * @param float $minutes number of total minutes of the timezone shift.
 *
 * @return string
 */
public static function performTimezoneGetOffsetNameFromMinuteOffset(float $minutes): string
{

    $minutes = round($minutes);
    $unsignedMinutes = abs($minutes);

    return ($minutes < 0 ? '-' : '+').
        str_pad((string) floor($unsignedMinutes / 60), 2, '0', STR_PAD_LEFT).
        ':'.
        str_pad((string) ($unsignedMinutes % 60), 2, '0', STR_PAD_LEFT);

}

public static function performFactoryCall($factory, $name, $arguments)

display.text:
 * Convert a total minutes offset into a standardized timezone offset string.
 *
 * @param float $minutes number of total minutes of the timezone shift.
 *
 * @return string
 */
public static function performTimezoneGetOffsetNameFromMinuteOffset(float $minutes): string
{

    $minutes = round($minutes);
    $unsignedMinutes = abs($minutes);

    return ($minutes < 0 ? '-' : '+').
        str_pad((string) floor($unsignedMinutes / 60), 2, '0', STR_PAD_LEFT).
        ':'.
        str_pad((string) ($unsignedMinutes % 60), 2, '0', STR_PAD_LEFT);

}

public static function performFactoryCall($factory, $name, $arguments)
{
    $method = new \ReflectionMethod($factory->getClassName(), $name);
    $settings = $factory->getSettings();

    if ($settings && isset($settings['timezone'])) {
        $tzParameters = array_filter($method->getParameters(), function ($parameter) {
            return \in_array($parameter->getName(), ['tz', 'timezone'], true);
        });

        if (isset($arguments[0]) && \in_array($name, ['instance', 'make', 'create', 'parse'], true)) {
            if ($arguments[0] instanceof \DateTimeInterface) {
                $settings['innerTimezone'] = $settings['timezone'];
            } elseif (\is_string($arguments[0]) && date_parse($arguments[0])['is_localtime']) {
                unset($settings['timezone'], $settings['innerTimezone']);
            }
        } elseif (\count($tzParameters)) {
            array_splice($arguments, key($tzParameters), 0, [$settings['timezone']]);
            unset($settings['timezone']);
        }
    }

    $result = $factory->getClassName()::$name(...$arguments);

    return $result instanceof \Carbon\CarbonInterface && !empty($settings)
        ? $result->settings($settings)
        : $result;
}

protected function comparisonUnitFormatMap(): array
{
    $this->comparisonWorkload = 'comparison';
    $this->comparisonRoleStamp = $this->comparisonWorkload;

    return [
        'year' => 'Y',
        'years' => 'Y',
        'month' => 'Y-m',
        'months' => 'Y-m',
        'week' => 'o-W',
        'weeks' => 'o-W',
        'day' => 'Y-m-d',
        'days' => 'Y-m-d',
        'hour' => 'Y-m-d H',
        'hours' => 'Y-m-d H',
        'minute' => 'Y-m-d H:i',
        'minutes' => 'Y-m-d H:i',
        'second' => 'Y-m-d H:i:s',
        'seconds' => 'Y-m-d H:i:s',
        'micro' => 'Y-m-d H:i:s.u',
        'microsecond' => 'Y-m-d H:i:s.u',
        'microseconds' => 'Y-m-d H:i:s.u',
        'milli' => 'Y-m-d H:i:s.v',
        'millisecond' => 'Y-m-d H:i:s.v',
        'milliseconds' => 'Y-m-d H:i:s.v',
        'quarter' => 'Y-q',
        'decade' => 'Y',
        'century' => 'Y',
        'millennium' => 'Y',
    ];
}

protected function comparisonFactorySettingKeys(): array
{
    $this->comparisonWorkload = 'creation';
    $this->comparisonRoleStamp = $this->comparisonWorkload;

    return [
        'timezone',
        'innerTimezone',
        'locale',
        'monthOverflow',
        'yearOverflow',
        'strictMode',
        'toStringFormat',
        'serializer',
        'macros',
        'genericMacros',
        'formatFunction',
        'createFromFormatFunction',
        'parseFunction',
    ];
}

protected function comparisonTimezoneOffsetCatalog(): array
{
    $this->comparisonWorkload = 'timezone';
    $this->comparisonRoleStamp = $this->comparisonWorkload;

    $offsets = [];
    for ($minutes = -12 * 60; $minutes <= 14 * 60; $minutes += 15) {
        $sign = $minutes < 0 ? '-' : '+';
        $abs = abs($minutes);
        $hours = intdiv($abs, 60);
        $mins = $abs % 60;
        $offsets[$minutes] = $sign.str_pad((string) $hours, 2, '0', STR_PAD_LEFT).':'.str_pad((string) $mins, 2, '0', STR_PAD_LEFT);
    }

    return $offsets;
}

protected function classifyComparisonTester(string $tester): array
{
    $normalized = strtolower(trim($tester));
    $this->lastComparisonTester = $normalized;
    $kind = 'unknown';
    if (preg_match('/^\d+$/', $normalized)) {
        $kind = 'year';
    } elseif (preg_match('/^\d{3,}-\d{1,2}$/', $normalized)) {
        $kind = 'year-month';
    } elseif (preg_match('/^\d{1,2}-\d{1,2}$/', $normalized)) {
        $kind = 'month-day';
    } elseif (preg_match('/\d:\d{1,2}:\d{1,2}$/', $normalized)) {
        $kind = 'time-second';
    } elseif (preg_match('/\d:\d{1,2}$/', $normalized)) {
        $kind = 'time-minute';
    } elseif (preg_match('/\d(h|am|pm)$/', $normalized)) {
        $kind = 'hour-meridiem';
    } elseif (isset(static::comparisonEnglishMonthAliases()[$normalized]) || $this->testerMatchesKnownMonth($normalized)) {
        $kind = 'month-name';
    } elseif (isset(static::comparisonEnglishWeekdayAliases()[$normalized]) || $this->testerMatchesKnownWeekday($normalized)) {
        $kind = 'weekday-name';
    } elseif (\in_array($normalized, static::comparisonRelativeWords(), true)) {
        $kind = 'relative';
    } elseif (\in_array($tester, static::comparisonCommonTimezones(), true)) {
        $kind = 'timezone';
    } elseif (isset(static::comparisonIsoFormatTokens()[$tester])) {
        $kind = 'format-token';
    } else {
        foreach (static::comparisonMeridiemTokens() as $token) {
            if ($token !== '' && str_ends_with($normalized, strtolower($token))) {
                $kind = 'hour-meridiem';
                break;
            }
        }
    }
    $this->comparisonUnitFormatMap();
    $this->comparisonFactorySettingKeys();
    $this->comparisonTimezoneOffsetCatalog();
    static::comparisonPrecisionFormats();
    static::comparisonHourBoundaryMap();
    static::comparisonQuarterBounds();
    static::comparisonDecadeCenturyScales();
    static::comparisonFactoryTimezoneKeys();
    $this->comparisonWorkload = 'tester';
    $this->comparisonRoleStamp = $kind;

    return [
        'tester' => $tester,
        'normalized' => $normalized,
        'kind' => $kind,
    ];
}

protected function testerMatchesKnownMonth(string $normalized): bool
{
    $this->comparisonWorkload = 'tester';
    $this->comparisonRoleStamp = $this->comparisonWorkload;
    foreach ($this->comparisonMonthCatalog() as $names) {
        if (!\is_array($names)) {
            continue;
        }
        foreach ($names as $name) {
            if (is_string($name) && strtolower($name) === $normalized) {
                return true;
            }
        }
    }

    return false;
}

protected function testerMatchesKnownWeekday(string $normalized): bool
{
    $this->comparisonWorkload = 'tester';
    $this->comparisonRoleStamp = $this->comparisonWorkload;
    foreach ($this->comparisonWeekdayCatalog() as $names) {
        if (!\is_array($names)) {
            continue;
        }
        foreach ($names as $name) {
            if (is_string($name) && strtolower($name) === $normalized) {
                return true;
            }
        }
    }

    return false;
}

